r=Path('/scratch/pwa209/horsehair-worm');area=r/'maintenance/storage-reserve-200k-v2-20261106'
assert area.resolve()==area and area.is_dir() and area.stat().st_uid==3164768
payload={'storage_policy.py': {'sha256': '0e8691671a32e2b55cfcd626d461c2708d11d05b00c0491721c6c3be13107f7d', 'bytes': 11118, 'data': ''}, 'policy.json': {'sha256': '2e8e2bd2c1f70aa988a9414d2b44d9ffd0f768f8bc2e329747b7839b2855f2d9', 'bytes': 1118, 'data': ''}, 'test_storage_policy.py': {'sha256': '37a51f28c97c5ae5f147b8f088acc259ce00c583fe6130312248616edbbe0c32', 'bytes': 8029, 'data': ''}, 'archive_continuation.py': {'sha256': 'eee13f9f3c1a188c3a9d24d2d27afa4d3ef9e8fb76d2a87d76d9844d2acbd532', 'bytes': 34014, 'data': ''}, 'test_archive_continuation.py': {'sha256': '7c716b17c01546aa3b822912b7cce31bc21edf304bd25671c05e9f299816455d', 'bytes': 16611, 'data': ''}, 'archive-native-test-contract.json': {'sha256': 'c2f88d64b7a11625da0027e84c727350fff52933c33415a1e597d1a56d0eb3e9', 'bytes': 985, 'data': ''}, 'release_census.py': {'sha256': '1ba208eed7a6f43bc733e281240baa23ccd471de5c235d566c02d2020b428e68', 'bytes': 22578, 'data': ''}, 'test_release_census.py': {'sha256': '9df676f9b723648985f356c894ee76bf68322356edb7dc60354a97b2758ec46d', 'bytes': 9342, 'data': ''}, 'activate_controllers.py': {'sha256': '7616f75060198ce4fcdc712936e2a34dff503f35d647dc81858a42c8ec578ca2', 'bytes': 31812, 'data': ''}, 'test_activate_controllers.py': {'sha256': 'ac87698ac8afcb7d208955e4f875d77982b89576b220fd1598caf8d94380d34b', 'bytes': 12525, 'data': ''}, 'prepare_study.py': {'sha256': '41e5a9b10297c856a90b42a62cab30617e6e77f4aa0b7d42c8f1eaaf0574068f', 'bytes': 28523, 'data': ''}, 'test_prepare_study.py': {'sha256': 'a8d8cd89f5e145752e533950bad06b7e9b87ace8339a562d14192c0f18cc9a35', 'bytes': 6822, 'data': ''}};request={'kind': 'finite-storage-reserve-200k-study-preparation', 'root': '/scratch/pwa209/horsehair-worm', 'source_pins': {'/scratch/pwa209/horsehair-worm/maintenance/storage-reserve-200k-v2-20261106/storage_policy.py': '0e8691671a32e2b55cfcd626d461c2708d11d05b00c0491721c6c3be13107f7d', '/scratch/pwa209/horsehair-worm/maintenance/storage-reserve-200k-v2-20261106/policy.json': '2e8e2bd2c1f